#pragma once
// Pre-rendered Garden pictures (garden_art.cpp, generated by tools/garden_art.py).
#include <stdint.h>
#include <stddef.h>

struct GardenArt {
  uint16_t w, h, ox;            // size; ox = left edge inside the 220 px plant frame (foot at x 110, bottom)
  const uint8_t *jpg; size_t jpgSize;
  const uint8_t *alpha; size_t alphaSize;
};
extern const GardenArt kGardenSeed, kGardenSprout;
extern const GardenArt kGardenPlant[8][4];   // [species][stage - STAGE_YOUNG]: young, grown, buds, bloom
extern const GardenArt kGardenPot;
extern const GardenArt kGardenFly[2];        // butterfly: wings open, closed
extern const GardenArt kGardenBackdrop;    // 480 px tree line + hedge behind the pot
